        begin: /\B\?(?:\\\d{1,3}|\\x[A-Fa-f0-9]{1,2}|\\u\{[A-Fa-f0-9]+\}|\\u[A-Fa-f0-9]{4}|(?:\\[CM]-)+\\?[^\s]|\\\S|\S)(?!\S)/
